  _ = `Undangan ini dibatalkan`,
  _ = `Bagaimana cara kerja undangan?`,
  _ = `Jika game-mu diundang untuk berpartisipasi di Penawaran Harian, kamu akan menerima email dan melihat game-mu ada dalam daftar di atas. Begini proses kerjanya dari poin tersebut:`,
  _ = `Pilih tanggal yang tersedia dalam enam bulan ke depan yang cocok untukmu.`,
  _ = `Visibilitas di Halaman Beranda Steam dan halaman tag yang berlaku berjalan selama 24 jam, sementara diskon akan aktif selama antara 7 hingga 14 hari tergantung dari panjang diskon yang dipilih. Diskon akan dimulai pukul 10.00 Waktu Pasifik pada tanggal yang dipilih.`,
  _ = `Saat kamu memilih tanggal, kamu juga harus memasukkan persentase diskon dan pilih paket mana yang ingin didiskon.`,
  _ = `Kami sarankan untuk memasukkan persentase diskon yang sama atau lebih baik dari diskon terbaik yang pernah kamu tawarkan sebelumnya.`,
  _ = `Jika kamu belum siap untuk menjadwalkan Penawaran Harianmu sekarang, undangan akan dapat kamu temukan di Dasbor Penawaran Harianmu. Harap perhatikan tanggal kedaluwarsanya.`,
