  _ = `Jika kamu sudah menjadwalkan diskon lain dalam periode 1 bulan dari Penawaran Harian, cobalah untuk pertahankan persentase diskon yang sama. Ketika kami memfiturkan game-mu di Penawaran Harian, kami ingin penawarannya sama baiknya atau lebih baik dari yang pernah kamu tawarkan sebelumnya.`,
