  _ = `Halaman Diskon`,
  _ = `Halaman Diskon (Draf)`,
  _ = `Event ini belum terlihat untuk publik, tapi kami menunjukkan ini kepadamu karena kamu memiliki game yang telah terdaftar di halaman diskon. Jika ini tidak terduga, silakan hubungi penyelenggara diskon.`,
  _ = `Seperti inilah event ini berjalan untukmu!`,
