  _ = `Game-game yang membutuhkan rating usia untuk penjualan di Jerman: 15 November`,
  _ = `Salah satu aplikasimu tidak memiliki rating usia Jerman. Mulai 15 November 2024, Steam tidak akan lagi menampilkannya ke pelanggan yang menelusuri toko Steam di Jerman. Untuk memastikan agar game-mu tersedia untuk penjualan di Jerman, silakan lengkapi dan publikasikan kuesioner bawaan Steam.`,
  _ = `Beberapa aplikasimu tidak memiliki rating usia Jerman. Mulai 15 November 2024, Steam tidak akan lagi menampilkannya ke pelanggan yang menelusuri toko Steam di Jerman. Untuk memastikan agar game-mu tersedia untuk penjualan di Jerman, silakan lengkapi dan publikasikan kuesioner bawaan Steam.`,
  _ = `Lihat Aplikasi yang Tersisa`,
  _ = `Tindakan Penting`,
  _ = `Penawaran Harian`,
  _ = `Kamu memiliki undangan untuk menjadwalkan Penawaran Harian.`,
  _ = `Kamu memiliki undangan untuk menjadwalkan Penawaran Harian yang akan segera kedaluwarsa.`,
  _ = `Email Kontak`,
  _ = `Tambahkan alamat email-mu atau rekan kerjamu untuk memastikan kamu menerima email penting dari Steam.`,
  _ = `Saat ini tidak ada pengguna yang ditentukan untuk menerima komunikasi dari Steamworks. Harap berikan izin "Menerima Komunikasi Steamworks" kepada satu pengguna atau lebih, dengan alamat email yang valid di bawah ini agar Steam dapat memberitahukan mereka tentang diskon mendatang, event, fitur-fitur baru, atau undangan khusus lainnya.`,
  _ = `Kelola perizinan`,
  _ = `Permintaan Alamat`,
  _ = `Alamat Diminta`,
  _ = `Valve ingin mengirimkan sesuatu kepadamu. Mohon berikan alamatmu, atau tolak, sebelum %1$s.`,
  _ = `Valve ingin mengirimkan sesuatu kepadamu. Batas waktunya adalah %1$s, tapi kamu masih dapat memberikan alamatmu, atau menolak.`,
  _ = `Valve ingin mengirimkan sesuatu kepadamu. Mohon berikan alamatmu, atau tolak.`,
  _ = `Masukkan Alamat`,
  _ = `Alamat Surat`,
  _ = `Dengan menambahkan alamat surat, kami dapat mengirimkan barang fisik kepadamu dan memilih lokasi terbaik untuk event Steamworks di masa mendatang.`,
  _ = `Alamat ini dapat berbeda dari alamat yang kamu berikan saat mendaftar ke Steamworks. Jika kamu memiliki beberapa lokasi bisnis di bawah satu akun Steamworks, masukkan setiap lokasi secara terpisah.`,
  _ = `Tambahkan Alamat Baru`,
  _ = `Nomor Telepon`,
  _ = `Akun partner Steamworks-mu akan lebih aman jika ditambahkan nomor telepon yang bisa menerima SMS.`,
  _ = `Tambahkan Nomor Telepon`,
  _ = `Informasi Bank Kedaluwarsa`,
  _ = `Kamu harus memperbarui informasi bankmu sebelum %1$s atau kami tidak akan dapat melakukan pembayaran.`,
  _ = `Informasi pembayaran yang tercatat untuk akunmu sudah tidak aktif selama lebih dari 12 bulan dan akan kedaluwarsa pada %1$s.<br><br>Jika tidak ada tindakan yang diambil sebelum tanggal kedaluwarsa, informasi pembayaran ini akan dinonaktifkan dan kami tidak akan dapat melakukan pembayaran kepadamu.`,
