  _ = `Anti-Cheat`,
  _ = `Jika game-mu menginstal anti-cheat mode kernel pada client, kamu harus memberitahukannya kepada pengguna di sini. Jika kamu memiliki solusi anti-cheat sendiri, atau anti-cheat tidak terdaftar di bawah ini, pilih "lainnya" dan masukkan informasinya.`,
  _ = `Kolom ini opsional jika game-mu mengintegrasikan anti-cheat berbasis client atau server yang tidak pada tingkat kernel. Namun, kami percaya bahwa akan lebih baik bagi game apa pun yang menggunakan teknologi anti-cheat untuk memberitahukannya kepada pemain.`,
  _ = `Layanan anti-cheat:`,
  _ = `Integrasi Tingkat Kernel`,
  _ = `Solusi anti-cheat ini akan menginstal atau memodifikasi file pada tingkat kernel OS.`,
  _ = `Solusi anti-cheat ini tidak akan memodifikasi file pada tingkat kernel OS.`,
  _ = `Pilih jika solusi anti-cheat milikmu menginstal file pada tingkat kernel OS untuk mode game apa pun.`,
  _ = `Menghapus Instalasi Sepenuhnya`,
  _ = `Hanya pilih ini jika kamu yakin bahwa semua file terkait anti-cheat yang diinstal game-mu juga dihapus dari disk saat game dihapus instalannya.`,
  _ = `Perlindungan Boot Diperlukan`,
  _ = `Jika game-mu memerlukan Boot Aman, TPM, atau tindakan perlindungan boot lainnya yang diaktifkan dalam mode game apa pun, silakan pilih kombinasi yang diperlukan.`,
