  _ = `Edisi Grup`,
  _ = `Jelaskan Edisimu...`,
  _ = `Antarmuka ini memungkinkanmu untuk menyediakan gambar yang menjelaskan perbedaan antara edisi-edisi game-mu (cth. Standar vs Deluxe, Game Tahun Ini, dll.). Edisi-edisi ini akan dikelompokkan dengan base game di bagian atas opsi pembelian, dan diurutkan dari harga terendah ke tertinggi di halaman toko. Untuk rincian lebih lanjut, silakan lihat <1>Dokumentasi "Jelaskan Edisimu"</1>.`,
