  _ = `Aturan Aset Grafis`,
  _ = `Sebelum melanjutkan, harap konfirmasikan bahwa gambarmu sudah mengikuti standar. Jika kamu mengirimnya untuk ditinjau dan persyaratannya tidak terpenuhi, tim peninjauan Steam akan menggagalkan peninjauan dan kamu perlu memperbaikinya sebelum melanjutkan. Rincian selengkapnya dapat kamu temukan di <1>dokumentasi Aturan Aset Grafis</1> milik kami.`,
