  _ = `Ini akan menambahkan gambar kapsul ke tampilan pembelian paket di toko, sama dengan cara konten bundel ditampilkan. Base app akan ditampilkan terlebih dahulu, kemudian aplikasi lain yang disertakan (dari harga tertinggi ke terendah).`,
  _ = `Hapus nama game dari awal item di dalam daftar isi paket.`,
  _ = `Untuk meningkatkan keterbacaan, hapus nama game, spasi, serta penghubung karakter seperti titik dua dan tanda hubung yang ada sebelum nama item-item seperti DLC dan soundtrack saat semua berada di area pembelian paket. Misalnya, "Half Life 2: Episode 1" akan muncul sebagai "Episode 1". Hanya nama base game, spasi, dan pemisah umum seperti tanda hubung dan titik dua yang akan disembunyikan.`,
  _ = `Simpan dan publikasikan`,
  _ = `Batal`,
  _ = `Event Pembaruan Besar yang Difiturkan`,
  _ = `Pemilik game akan diarahkan ke event di perpustakaan mereka untuk mendapatkan info lebih lanjut. Steam mencari event yang terkait dengan base game.`,
  _ = `[Siap @ %1$s] Nama Event: %2$s`,
  _ = `[Draf] Nama Event: %2$s`,
  _ = `[Dimulai: %1$s] Nama Event: %2$s`,
  _ = `Event yang memenuhi syarat tidak ditemukan. Draf atau postingan baru (dalam satu bulan terakhir) diperlukan. <1>Lihat Dasbor Event & Pengumuman</1>`,
  _ = `Peletakan logomu telah tersimpan. Kamu bisa memublikasikan perubahan ini via Admin Halaman Toko.`,
  _ = `Pengelolaan Diskon`,
  _ = `Tanggal diskon dapat berubah sewaktu-waktu. Berhati-hatilah saat mengumumkan tanggal secara publik, terutama untuk event yang akan berlangsung jauh di kemudian hari.`,
  _ = `Catatan`,
  _ = `Ingat: Kamu tidak dapat mendiskon game-mu dalam 30 hari setelah perilisan pertamanya dalam harga penuh atau setelah kenaikan harga dalam mata uang apa pun. Mohon lihat %1$s untuk rincian lebih lanjut.`,
  _ = `dokumentasi`,
  _ = `Diskon dimulai dan berakhir pada pukul 10.00 Waktu Pasifik, kecuali ditentukan lain.`,
  _ = `Diskon Kustom`,
  _ = `Buat Diskon...`,
  _ = `+ Buat Baru`,
  _ = `Buat diskon kustom atau aktifkan penawaran seminggu penuh untuk game yang ingin kamu ikut sertakan.`,
  _ = `Impor/Ekspor Diskon`,
  _ = `Alat`,
  _ = `Impor/Ekspor CSV...`,
  _ = `Diskon untuk paket game-mu juga bisa dikelola dengan mengedit file .csv. Ini berguna jika kamu ingin memperbarui banyak diskon sekaligus atau memeriksa konsistensi pada katalog game yang besar.`,
  _ = `Unduh tabel diskon dari dasbor ke file CSV. Tabel ini akan memuat perubahan-perubahan yang masih tertunda dan belum disimpan.`,
  _ = `Unduh semua`,
  _ = `Unduh diskon untuk semua paket.`,
  _ = `Unduh yang terlihat`,
  _ = `Unduh diskon untuk paket-paket yang terlihat, kecuali yang kamu sembunyikan dengan menciutkan baris atau dengan filter teks.`,
  _ = `Unggah file CSV dengan tabel diskon yang telah diperbarui. Entri yang tidak sesuai dengan diskon yang tercatat akan dimasukkan ke dasbor sebagai pembaruan yang masih tertunda. Kamu bisa meninjaunya dulu sebelum mengirimnya.`,
  _ = `Unggah diskon baru`,
