  _ = `%1$s diskon telah diperbarui secara lokal.`,
  _ = `Tinjau perubahan-perubahan ini sekarang sebelum menyimpan atau klik OK untuk kembali ke dasbor dengan perubahan-perubahan yang masih menunggu secara lokal.`,
  _ = `Menemukan %1$s eror:`,
  _ = `Buat Diskon`,
  _ = `Jadwalkan diskon baru untuk satu paket.`,
  _ = `Pilih paket untuk melihat berbagai opsi diskon yang tersedia.`,
  _ = `Semua opsi diskon untuk enam bulan ke depan untuk paket ini telah dicatat.`,
  _ = `Diskon akan dimulai dan berakhir secara otomatis pada tanggal-tanggal berikut. Jika diskon sudah dimulai, kamu tidak akan bisa memodifikasinya lagi. Jadi, rencanakanlah baik-baik.`,
