  _ = `Batal Mendaftar`,
  _ = `Edit Pendaftaran`,
  _ = `Lihat Pendaftaran`,
  _ = `Daftarkan ketertarikanmu`,
  _ = `Klik di bawah ini untuk mendaftarkan ketertarikanmu untuk event ini dan untuk dapat mengikuti diskon. Dengan mendaftar, kami akan memberikanmu informasi penting tentang event ini menjelang tanggal mulai. Pendaftaran dapat dibatalkan kapan saja.`,
  _ = `Eror`,
  _ = `Paket ini dirilis dalam %1$s hari periode diskon ini`,
  _ = `Game di paket ini pernah dinaikkan harganya setidaknya dalam satu mata uang dalam %1$s hari periode diskon ini`,
  _ = `Sudah ada diskon yang dijadwalkan untuk paket ini dalam %1$s hari periode diskon ini`,
  _ = `Sudah ada diskon yang dijadwalkan untuk paket ini selama periode ini.`,
  _ = `SIMPAN DISKON?`,
  _ = `Dengan menyimpan perubahan, %1$s diskon akan diperbarui dan %2$s diskon baru akan dibuat.`,
  _ = `Dengan menyimpan perubahan, 1 diskon akan diperbarui.`,
  _ = `Dengan menyimpan perubahan, %1$s diskon akan diperbarui.`,
