  _ = `Dengan menyimpan perubahan, %1$s diskon baru akan dibuat.`,
  _ = `EROR: kegagalan server. Silakan coba lagi.`,
  _ = `Kamu tidak bisa memasukkan diskon di bawah 10%.`,
  _ = `Kamu harus masukkan diskon yang lebih kecil untuk beberapa paket, karena harga yang sudah didiskon tidak boleh kurang dari setara 0,49 USD dalam mata uang mana pun atau di wilayah mana pun.`,
  _ = `Kamu tidak bisa memasukkan diskon yang lebih besar dari %1$s% untuk paket ini karena harga yang sudah didiskon tidak boleh kurang dari setara 0,49 USD dalam mata uang mana pun atau di wilayah mana pun.`,
  _ = `Harga dasar paket ini dalam satu mata uang atau lebih, berada di bawah nilai minimum yang diizinkan. Karenanya, kamu tidak dapat memasukkan diskon untuk paket ini.`,
  _ = `Paket yang ditandai dengan simbol ini sedang ditambahkan ke diskon yang sedang berlangsung. Diskon yang kamu masukkan akan segera dimulai setelah disimpan.`,
  _ = `Diskon terjadwal ini akan menyebabkan harga paket ini berada di bawah harga minimum yang disyaratkan dalam satu mata uang atau lebih. Dengan demikian, paket ini tidak akan dapat dibeli di negara-negara tersebut. Untuk memastikan paket ini dapat dibeli di mana saja, kamu harus memasukkan persentase diskon kurang dari %1$s% untuk paket ini.`,
  _ = `Harga dasar paket ini dalam satu mata uang atau lebih berada di bawah nilai minimum yang diizinkan. Dengan demikian, paket ini tidak akan dapat dibeli di negara-negara tersebut atau negara lain di mana diskon ini menyebabkan harga turun di bawah persyaratan nilai minimum. Untuk memastikan paket ini dapat dibeli di mana saja, harap perbarui harga paket ini setidaknya ke nilai minimum Steam.`,
  _ = `Kamu punya 1 perubahan yang belum disimpan. Membuangnya akan membatalkan diskon-diskon baru dan mengembalikan diskon-diskon yang telah diperbarui ke pengaturan sebelumnya.`,
  _ = `Kamu punya %1$s perubahan yang belum disimpan. Membuangnya akan membatalkan diskon-diskon baru dan mengembalikan diskon-diskon yang telah diperbarui ke pengaturan sebelumnya.`,
