  _ = `Sembunyikan paket yang berkendala`,
  _ = `Kamu bisa memfilter berdasarkan nama paket atau ciutkan bagian game ke kiri.`,
  _ = `DISKON SEMUA PAKET YANG TERLIHAT`,
  _ = `Masukkan diskon antara 10% dan 95%.`,
  _ = `Kamu juga bisa masukkan "0" untuk menghapus diskon-diskon dari semua paket yang terlihat.`,
  _ = `Dengan ini, semua paket yang terlihat akan diberikan diskon, termasuk menimpa diskon yang pernah ditetapkan sebelumnya. Ini sama dengan memasukkan angka di setiap kotak secara terpisah. Kamu selalu memiliki opsi untuk meninjau dan mengonfirmasi sebelum perubahan diterapkan.`,
  _ = `CATATAN: setidaknya satu dari paket-paket ini hanya bisa didiskon sampai %1$s%.`,
