  _ = `Paket ini memiliki harga dalam satu mata uang atau lebih yang berada di bawah nilai minimum yang diizinkan. Gulir ke kanan untuk melihat mata uang spesifik dengan peringatan.`,
  _ = `Paket ini memiliki satu diskon terjadwal atau lebih yang akan membuat harga game berada di bawah nilai minimum yang diizinkan dalam satu mata uang atau lebih. Gulir kanan untuk melihat peringatan spesifik.`,
