  _ = `Dokumentasi`,
  _ = `Hubungi Kami`,
  _ = `Konversikan Harga...`,
  _ = `Jika kamu ingin memperbarui cepat harga dalam semua mata uang, gunakan tombol ini untuk menerapkan harga yang dikonversi berdasarkan harga USD. Kamu akan dapat meninjau perubahan harga sebelum mengajukan.`,
  _ = `Konversikan dari Harga USD`,
  _ = `Hargamu sudah sesuai dengan metode konversi yang dipilih`,
  _ = `Harga yang Direkomendasikan`,
  _ = `Untuk membantumu mengelola harga di 35+ mata uang yang didukung Steam, alat ini menawarkan metode konversi untuk mengubah harga USD dasar ke level yang sesuai dengan wilayah. Konversi ini didasarkan pada kombinasi nilai mata uang, daya beli wilayah, pajak yang diwajibkan, dan pengalaman kami sendiri menjual di wilayah tertentu.`,
  _ = `Dengan mengeklik tombol di bawah, harga yang dikonversikan akan diterapkan ke semua paket yang terlihat, kecuali yang kamu sembunyikan dengan menciutkan baris atau dengan filter teks.`,
  _ = `Pelajari lebih lanjut tentang harga yang dikonversikan Steam sesuai wilayah.`,
  _ = `Kamu akan dapat meninjau ulang dan mengonfirmasi segala perubahan sebelum semuanya diterapkan.`,
