  _ = `Berikut adalah harga-harga yang sudah dipublikasikan untuk paket ini.`,
  _ = `Butuh ditinjau`,
  _ = `Simpan perubahan-perubahan ini untuk mengirimkan harga-harga baru untuk ditinjau.`,
  _ = `Sedang ditinjau`,
  _ = `Otomatis dipublikasikan`,
  _ = `Harga-harga yang disorot adalah harga baru yang dimasukkan oleh %1$s pada %2$s. Steam akan memublikasikan perubahan-perubahan ini setelah ditinjau.`,
  _ = `Sedang ditinjau`,
  _ = `Harga-harga yang disorot adalah harga baru yang dimasukkan oleh %1$s pada %2$s. Kamu bisa memublikasikan perubahan-perubahan ini setelah ditinjau.`,
  _ = `Telah ditinjau`,
  _ = `Kamu dapat memublikasikan harga-harga ini sekarang.`,
  _ = `Klik "Simulasikan Harga Baru" untuk mengunci harga-harga ini. Harga akan berlaku secara otomatis saat game-mu dirilis.`,
  _ = `PUBLIKASIKAN`,
  _ = `PUBLIKASIKAN...`,
  _ = `PUBLIKASIKAN HARGA-HARGA BARU?`,
  _ = `Dengan memublikasikannya, maka perubahan harga ini akan terlihat di toko.`,
  _ = `Dengan memublikasikannya, maka %1$s perubahan harga ini akan terlihat di toko.`,
  _ = `Ingat: Kamu tidak bisa mendiskon paket ini dalam 30 hari setelah memublikasikan kenaikan harga dalam mata uang apa pun.`,
  _ = `Sudah ada diskon yang dijadwalkan untuk paket ini dalam 30 hari ke depan dan perubahan harga yang kamu buat mencakup kenaikan harga dalam satu atau lebih mata uang.`,
  _ = `Silakan lihat dokumentasi <1>Aturan Penentuan Harga</1> untuk rincian lebih lanjut mengenai waktu jeda setelah menaikkan harga.`,
  _ = `Kamu memiliki beberapa opsi:`,
  _ = `Tarik paket ini dari diskon apa pun yang dijadwalkan dalam 30 hari ke depan. Setelah selesai, kamu dapat kembali ke sini dan publikasikan perubahan hargamu.`,
  _ = `Tunggu dan publikasikan perubahan harga ini segera setelah diskon terjadwalmu yang berikutnya berakhir.`,
  _ = `TIDAK DAPAT MEMUBLIKASIKAN SEKARANG`,
  _ = `<1>Terjadi kesalahan saat mempersiapkan untuk memublikasikan perubahan harga ini.</1><2>Silakan coba lagi dan hubungi Valve jika kamu terus mengalami kendala ini.</2>`,
  _ = `<1>Terjadi kesalahan saat mencoba untuk memublikasikan perubahan harga ini.</1><2>Silakan coba lagi dan hubungi Valve jika kamu terus mengalami kendala ini.</2>`,
  _ = `tampilan ringkas`,
  _ = `Pilih harga di bawah ini untuk menentukan harga dalam USD dan terapkan harga konversi yang direkomendasikan untuk semua mata uang lain.`,
  _ = `Filter ke paket di bawah harga minimum (%1$s)`,
  _ = `Tampilkan semua paket`,
  _ = `Tampilkan paket dengan perubahan harga yang diajukan`,
  _ = `Tampilkan paket yang diubah secara lokal`,
  _ = `Kamu tidak bisa menaikkan harga langganan. Silakan hubungi Steam jika kamu ingin melakukannya.`,
  _ = `Harga harus setidaknya %1$s. Jika masih berada di bawah nilai minimum, paket ini tidak dapat dibeli oleh pelanggan di negara-negara yang menggunakan mata uang ini.`,
  _ = `Hargamu saat ini berada di bawah harga yang biasanya diizinkan untuk mata uang ini. Tidak masalah untuk mempertahankan harga ini, tapi hal itu akan membatasi seberapa besar diskon yang dapat diberikan untuk game-mu agar harga setelah diskon tetap di atas jumlah transaksi minimum yang diizinkan.`,
  _ = `%1$s: Harga %2$s untuk %3$s berada di bawah harga minimum %2$s dari %4$s. Periksa jika ada kesalahan ketik, seperti angka yang hilang, silakan masukkan %4$s atau lebih.`,
  _ = `%1$s: Harga %2$s dari %3$s lebih tinggi dari harga yang dipublikasikan saat ini yaitu %4$s. Harga langganan berulang tidak dapat dinaikkan, jadi harap masukkan %4$s atau kurang, atau hubungi Steam jika kamu perlu menaikkannya.`,
  _ = `1 perubahan harga di bawah ini juga berada di luar rentang yang diizinkan.`,
  _ = `%1$s perubahan harga di bawah ini juga berada di luar rentang yang diizinkan.`,
  _ = `Harga-harga ini tidak dapat diajukan sampai diperbaiki. Lihat dokumentasi <1>Aturan Penentuan Harga</1> untuk rincian.`,
  _ = `Berdasarkan metode konversi yang kamu pilih dan harga USD, harga yang dimasukkan jauh lebih tinggi dari harga yang disarankan (%1$s).`,
  _ = `Berdasarkan metode konversi yang kamu pilih dan harga USD, harga yang dimasukkan jauh lebih rendah dari harga yang disarankan (%1$s).`,
  _ = `Berdasarkan metode konversi dan harga USD yang dipilih, harga yang dimasukkan jauh lebih rendah daripada yang disarankan (%1$s). Harga ini akan membatasi diskon, yaitu maksimum sebesar %2$s%, sehingga harga setelah diskon tetap setara dengan 0,49 USD.`,
  _ = `Harga yang dimasukkan %1$s lebih besar dari harga yang saat ini disimpan.`,
  _ = `Harga yang dimasukkan %1$s lebih kecil dari harga yang saat ini disimpan.`,
  _ = `Harga rendah ini akan membatasi diskon ke maksimum %1$s% agar harga yang didiskon setidaknya tetap setara 0,49 USD.`,
  _ = `Harga ini akan membatasi diskon ke maksimum %1$s% agar harga yang didiskon setidaknya tetap setara 0,49 USD.`,
  _ = `BARU`,
  _ = `Harga yang dipublikasikan:`,
  _ = `Ini adalah harga yang saat ini dipublikasikan di toko.`,
  _ = `Dalam peninjauan: belum ada yang harus dilakukan`,
  _ = `Dalam peninjauan: Steam akan memublikasikannya untukmu`,
  _ = `Ditinjau: siap untuk kamu publikasikan`,
  _ = `Ditinjau: siap untuk kamu simulasikan`,
  _ = `Hargamu telah diajukan dan sedang menunggu peninjauan. Setelah kami meninjaunya, kamu akan kembali ke sini untuk memublikasikannya.`,
  _ = `Hargamu telah diajukan dan sedang menunggu peninjauan. Setelah kami meninjaunya, kamu akan kembali ke sini untuk menyimulasikannya untuk tahap perilisan.`,
  _ = `Hargamu telah diajukan dan sedang menunggu peninjauan. Steam akan memublikasikannya untukmu setelah peninjauan selesai sehingga tidak ada lagi yang perlu kamu lakukan.`,
  _ = `Hargamu telah diajukan dan sedang menunggu peninjauan. Harga di toko tidak akan berubah sampai kamu memublikasikannya di bawah ini.`,
  _ = `Hargamu telah diajukan dan sedang menunggu peninjauan. Simulasikan di bawah dan harga-harga akan diterapkan saat game-mu dirilis.`,
  _ = `Harga yang diusulkan:`,
  _ = `Harga ini diusulkan oleh %1$s pada %2$s dan masih menunggu peninjauan.`,
  _ = `Harga yang disetujui:`,
  _ = `Harga yang diusulkan ini telah ditinjau dan siap untuk dipublikasikan.`,
  _ = `Harga yang direkomendasikan:`,
  _ = `Harga ini direkomendasikan berdasarkan harga USD sebesar %1$s.`,
  _ = `PILIH`,
  _ = `Klik untuk mengusulkan harga ini untuk ditinjau.`,
  _ = `Klik untuk kembali ke harga yang telah dipublikasikan.`,
  _ = `Pulihkan semua perubahan yang belum disimpan untuk %1$s`,
  _ = `Pulihkan semua perubahan yang belum disimpan untuk paket ini`,
