  _ = `Gambar Sampul Event`,
  _ = `Gambar Tajuk Event`,
  _ = `Gambar Tajuk Event`,
  _ = `Kapsul Tajuk Aplikasi (Promo)`,
  _ = `Penggunaan: Gambar ini merepresentasikan event diskonmu di spot Penawaran Harianmu di halaman beranda Steam.`,
  _ = `Desain: Harus menyertakan logo event di atas kisi game paling populermu sehingga dapat dikenali oleh pemain.`,
  _ = `Kapsul Utama Aplikasi (Promo)`,
  _ = `Penggunaan: Gambar ini mewakili event diskonmu dan terkadang digunakan ketika kami perlu menyajikan promosi di lokasi alternatif.`,
  _ = `Desain: Harus menyertakan logo event di atas kisi game paling populermu sehingga dapat dikenali oleh pemain.`,
  _ = `Selengkapnya tentang Penawaran Tengah Minggu`,
  _ = `Selengkapnya tentang Penawaran Akhir Minggu`,
  _ = `Selengkapnya tentang Promosi Pemfituran`,
  _ = `Tenggat waktu:`,
  _ = `Masukkan URL di mana kami dapat mengunduh file PSD ber-layer milikmu dan fon apa pun yang kamu gunakan.`,
  _ = `Unggah file-file pratinjau untuk masing-masing aset di bawah (%1$s)`,
  _ = `%1$s/%2$s selesai`,
  _ = `Tinjau file pratinjau dari masing-masing aset untuk memastikan gambar sudah sesuai dengan templat ukuran dan pemotongan kami`,
  _ = `Taruh file .psd dan file fon non-standar apa pun yang kamu gunakan ke Dropbox atau Google Drive atau layanan penyimpanan media serupa lainnya, lalu bagikan URL-nya pada kami di bawah ini.`,
  _ = `Lokasi file asetmu`,
