  _ = `Mengekstraksi satu elemen dari tensor yang masuk, dan menghasilkan output berupa elemen yang diekstraksi tersebut, serta tensor masuk yang dikurangi nilai yang diekstraksi.`,
  _ = `Menggunakan tensor n-dimensional dan membuat grup KMeans untuknya, atau menggunakan grup KMeans bernama untuk menerjemahkan nilai input menjadi index grup`,
