  _ = `Menormalkan vektor sehingga semua nilai berjumlah 1,0`,
  _ = `Menetapkan penanda dalam model yang dapat disimpulkan, dengan node yang terhubung sebagai output dan menggunakan nama yang sudah ditentukan.`,
  _ = `Concat`,
  _ = `Menggabungkan menjadi satu tensor. Semua bentuk input harus sama kecuali sumbu concat.`,
  _ = `Membuat penyematan dari nilai-nilai dalam tensor yang masuk`,
  _ = `Layer jaringan neural yang terhubung dengan padat`,
