  _ = `Layer yang diputuskan yang menghilangkan beberapa nilai dari tensor input selama pelatihan`,
  _ = `Node yang menormalisasi nilai yang masuk ke rata-rata 0 dan satu stddev antara -1 sampai 1.`,
