  _ = `Langkah %1$s`,
  _ = `Dukungan INPUT UMUM`,
  _ = `Untuk menggambarkan dengan baik level dukungan kontroler game untuk pemain, kami memiliki wisaya singkat berisi beberapa pertanyaan. Mohon lengkapi wisaya ini dengan menjawab pertanyaan sesuai dengan pengetahuanmu agar Steam dapat menghubungkan pemain dengan game yang dapat dijalankan dengan baik menggunakan perangkat yang dimiliki.`,
  _ = `Perlu diingat bahwa perangkat VR, termasuk perangkat input, yang didukung game-mu harus dijelaskan di persyaratan sistem. Dukungan kontroler yang dijelaskan di sini mengacu pada desktop atau dukungan Mode Big Picture.`,
  _ = `Perangkat apa yang bisa digunakan agar kamu dapat memainkan game-mu dengan nyaman?`,
  _ = `Hanya mouse dan keyboard`,
  _ = `Mouse dan keyboard, juga gamepad`,
  _ = `Mouse dan keyboard, tapi gamepad lebih diutamakan`,
  _ = `Gamepad Diperlukan; Tidak ada dukungan untuk mouse dan keyboard`,
  _ = `Ya, game saya memenuhi kriteria di atas untuk dukungan penuh`,
  _ = `Tidak, game saya tidak memenuhi semua kriteria di atas`,
  _ = `Kontroler DualShock (USB)`,
  _ = `Kontroler DualShock (USB+Bluetooth)`,
  _ = `Kontroler DualSense (USB)`,
  _ = `Kontroler DualSense (USB+Bluetooth)`,
  _ = `Tidak, game saya tidak mendukung Kontroler PlayStation`,
  _ = `Ya, game saya memiliki integrasi API Steam Input penuh`,
  _ = `Tidak, game saya tidak menggunakan API Steam Input`,
  _ = `Dukungan Kontroler Xbox`,
  _ = `Jika game-mu memiliki dukungan Kontroler Xbox secara penuh, pemain dapat meluncurkan, mengonfigurasikan, memainkan, dan keluar dari game-mu tanpa menggunakan keyboard. Untuk membuktikan bahwa game-mu memiliki dukungan Kontroler Xbox secara penuh, hal-hal berikut ini harus bisa dilakukan di game-mu:`,
  _ = `Pemain harus dapat melakukan semua tindakan di dalam game hanya dengan menggunakan kontroler. Ini termasuk melewati semua peluncur pra-game, memainkan game-nya, berinteraksi dengan menu, mengubah pengaturan, dan keluar dari game.`,
  _ = `Ketika kontroler terputus, game harus terjeda, kecuali pada game multipemain.`,
  _ = `Keyboard virtual harus muncul di layar setiap kali ada permintaan untuk memasukkan teks.`,
  _ = `Jika game-mu mendukung multipemain lokal, mode tersebut harus berfungsi dengan banyak kontroler.`,
  _ = `Apakah game-mu memenuhi kriteria di atas untuk dukungan Kontroler Xbox secara penuh?`,
  _ = `Dukungan Kontroler PlayStation`,
  _ = `Jika game-mu mendukung satu atau lebih model Kontroler PlayStation yang tercantum di bawah, secara umum perangkat tersebut dapat digunakan untuk melakukan semua hal dalam game yang dapat dilakukan menggunakan Kontroler Xbox. Selain itu, game-mu harus melakukan hal berikut ini agar dianggap mendukung Kontroler PlayStation:`,
  _ = `Menampilkan glif (ikon) di layar ketika pengguna diminta untuk menekan tombol tertentu pada kontroler.`,
  _ = `Memainkan game, berinteraksi dengan menu, mengubah pengaturan, keluar dari game.`,
  _ = `<1>Catatan untuk USB/Bluetooth:</1> Untuk kontroler PlayStation di PC, koneksi USB biasanya bekerja dengan baik, tapi tidak sama halnya ketika menggunakan koneksi Bluetooth. Mohon konfirmasikan dengan tim teknismu bahwa koneksi Bluetooth benar-benar dapat bekerja dengan baik sebelum memilih pilihan di bawah.`,
  _ = `<1>Ya</1>, game saya mendukung: (pilih semua yang sesuai)`,
  _ = `Integrasi API Steam Input`,
  _ = `Jika game-mu telah sepenuhnya terintegrasi/terkalibrasi API Steam Input, maka pemain akan dapat menggunakan 200+ model kontroler untuk memainkannya, termasuk model-model yang akan datang. Untuk membuktikan bahwa game-mu mendukung ini, paling tidak hal-hal berikut ini harus bisa dilakukan:`,
  _ = `Implementasikan tindakan API Steam Input dan minta sumber tindakan terkait untuk menampilkan glif kontroler dalam game yang tepat untuk jenis kontroler utama.`,
  _ = `Menjeda game secara otomatis jika kontroler terputus.`,
  _ = `Pemain harus dapat memetakan ulang tombol-tombol di kontroler yang mereka gunakan melalui konfigurator Steam.`,
  _ = `Jika kamu ragu, tanyakan kepada tim teknismu apakah mereka menggunakan API Steam Input.`,
  _ = `Apakah game-mu memanfaatkan API Steam Input secara penuh seperti yang dideskripsikan di atas?`,
  _ = `Wisaya Dukungan Kontroler`,
  _ = `Rangkuman`,
  _ = `Berdasarkan yang kamu beri tahukan kepada kami perihal dukungan kontrolermu, Steam akan menampilkan perincian sebagai berikut:`,
  _ = `Berdasarkan yang kamu beri tahukan kepada kami perihal dukungan kontrolermu, Steam tidak akan menampilkan perangkat game pad apa pun yang didukung.`,
  _ = `Gagal menemukan pesan pemasaran untuk ditinjau. Silakan periksa perizinanmu atau coba lagi nanti.`,
