  _ = `Minta Key Uji Game`,
  _ = `Gunakan formulir ini untuk meminta Steam Key untuk paket Playtest. Semua permintaan Steam Key ditinjau satu per satu oleh Valve, biasanya dalam kurun waktu 48—72 jam.`,
  _ = `Silakan gunakan kotak di bawah ini untuk memberi tahu kami lebih lanjut tentang tujuan penggunaan Key ini sehingga kami dapat membantu memastikan bahwa jumlah Key yang diminta sesuai dengan kebutuhanmu.`,
