  _ = `Diizinkan di: %1$s`,
  _ = `Dibatasi di: %1$s`,
  _ = `Sepertinya kamu masih harus melengkapi <1>Survei Konten</1>, kemungkinan dapat menghapus pembatasan yang disebabkan oleh tidak adanya rating.`,
  _ = `Perekaman Game - Pengelolaan Ikon Garis Waktu`,
  _ = `Ikon yang dibuat di sini bisa merupakan referensi dari game untuk menandai momen tertentu dalam garis waktu rekaman game. Steam juga memliki set ikon default yang bisa kamu gunakan. Lihat dokumentasi untuk rinciannya.`,
