  _ = `Buat Ikon Garis Waktu Baru`,
  _ = `Edit Ikon (%1$s) `,
  _ = `Ikon`,
  _ = `Pratinjau Garis Waktu:`,
  _ = `Pengenal unik`,
  _ = `Digunakan oleh Panggilan API (maks. %1$s karakter)`,
  _ = `Pengenal unik pada ikon publik tidak dapat diedit`,
  _ = `Warna`,
  _ = `masukkan pengenal unik...`,
  _ = `Digunakan oleh panggilan API (maks. %1$s karakter). Harus huruf kecil alfanumerik. Panjangnya minimal 3 karakter. Juga mendukung '_' dan '-'. Tidak boleh ada spasi kosong.`,
  _ = `Pengenal berisi karakter yang tidak didukung. Harus huruf kecil alfanumerik. Panjangnya minimal 3 karakter. Juga mendukung '_' dan '-'. Tidak boleh ada spasi kosong.`,
  _ = `Nama penanda tidak dapat dimulai dengan "steam_" yang khusus digunakan untuk ikon resmi.`,
  _ = `Untuk setiap ikon, unggah file .PNG atau .SVG dan berikan pengenal unik yang akan digunakan oleh panggilan API.`,
  _ = `Ikon (file .SVG or .PNG)`,
  _ = `Ikon SVG akan ditampilkan dalam jendela tampilan berukuran 36 px x 36 px. Harap buat aset yang sesuai. File PNG harus merupakan aset persegi berukuran 24 px x 256 px (lebar x tinggi).`,
  _ = `Ikon SVG akan ditampilkan dalam jendela tampilan berukuran 36 px x 36 px. Harap buat aset yang sesuai. File PNG harus merupakan aset persegi berukuran 24 px x 256 px (lebar x tinggi).`,
  _ = `File SGV ini memiliki kotak tampilan atau lebar/tinggi %1$s dan dapat menampilkan hasil yang tidak benar.`,
  _ = `Cari file...`,
  _ = `Cari file...`,
  _ = `Atau seret dan lepas file di sini`,
  _ = `Visibilitas`,
