  _ = `jenis konten tidak diketahui: %1$s`,
  _ = `Eror: PNG harus berbentuk persegi. Gambar harus memiliki lebar dan tinggi yang sama.`,
  _ = `Eror: PNG harus berukuran setidaknya %1$s px x %1$s px dan berbentuk persegi.`,
  _ = `%1$s Ikon Menunggu`,
  _ = `%1$s Ikon Menunggu`,
  _ = `Penanda garis waktu baru atau yang diperbarui harus dipublikasikan dengan pengaturan Steamworks lainnya.`,
  _ = `Publikasikan`,
  _ = `Ikon Publik`,
  _ = `Ini dapat diakses dari semua branch, termasuk branch default-mu melalui panggilan API.`,
  _ = `Sebagai ikon publik, ini bisa merupakan referensi dari sesuatu dan tidak dapat dihapus atau berganti nama. Kamu bisa memperbarui gambar jika diperlukan.`,
  _ = `Buat ikon baru sebagai "publik" jika kamu ingin mempersiapkan perilisan publik`,
  _ = `Ikon yang Disembuyikan`,
  _ = `Gunakan ikon yang disembunyikan untuk menguji sebelum membuatnya terlihat ke publik. Gunakan set di bawah ini untuk mengasosiasikan suatu ikon dengan branch build tertentu jika kamu ingin membatasi akses.`,
  _ = `Gunakan ikon yang disembuyikan untuk menguji sebelum membuatnya terlihat ke publik.`,
  _ = `belum ditetapkan`,
  _ = `Ikon ini tidak akan ditampilkan di build apa pun`,
  _ = `Pindahkan Semua penanda tersembunyi ke publik`,
  _ = `Unduh untuk pengujian lokal`,
  _ = `Membuat sebuah file .SVG yang dapat digunakan oleh Steam untuk merender ikon. Ini akan membuat file berisi semua ikon publik dan ikon di set tersembunyi.`,
  _ = `Buat ikon baru sebagai "disembunyikan" jika kamu ingin menguji sebelum memublikasikannya`,
  _ = `Terbatas untuk branch: `,
  _ = `Tidak ada branch yang dipilih`,
  _ = `Buah Set Branch Baru`,
  _ = `Set Branch membantumu mengelola pengujian ikon yang disembuyikan dengan membatasi akses ke ikon hanya ke build pada branch spesifik`,
  _ = `Set Branch Tanpa Nama: %1$s`,
  _ = `Dibatasi oleh Branch`,
  _ = `Buat ikon menjadi terlihat hanya untuk branch build terpilih`,
  _ = `Set Branch: %1$s`,
  _ = `Edit Pilihan Branch`,
  _ = `Publikasikan Branch`,
  _ = `Duplikasi Penanda Garis Waktu`,
  _ = `Pilih penanda yang sudah dipublikasikan dari daftar di bawah ini untuk menduplikasi ke Set Branch %1$s (mengecualikan penanda yang sudah ada di Set Branch).`,
  _ = `Duplikasi penanda garis waktu berhasil. `,
  _ = `Kamu memiliki opsi untuk memilih satu atau lebih branch untuk diasosiasikan dengan item ini. Pemain mana pun yang memilih branch yang dipilih akan dapat melihat asetnya. Jika branch yang tidak dilindungi oleh kata sandi dipilih, maka ikon akan menjadi dapat dilihat oleh publik.`,
  _ = `Tidak ada perubahan yang dilakukan pada daftar branch`,
  _ = `Perubahan dibuat pada daftar branch. %1$s nama branch ditambahkan. %2$s nama branch dihapus.`,
  _ = `Branch ini dilindungi kata sandi.`,
  _ = `Buah Set Branch Baru`,
  _ = `Edit Set Branch`,
  _ = `Nama Set Branch (khusus internal)`,
  _ = `Deksripsi Set Branch (khusus internal, opsional)`,
  _ = `Nama tidak dapat dimulai dengan "steam_"`,
  _ = `Masukkan Nama untuk Set Branch.`,
  _ = `Publikasikan Tindakan`,
  _ = `Icon di bawah ini akan dipublikasikan:`,
  _ = `%2$s memiliki %1$s ikon untuk dipublikasikan.`,
  _ = `%2$s memiliki %1$s ikon untuk dipublikasikan.`,
  _ = `✔ %1$s dipublikasikan!`,
  _ = `Seret ikon yang disembunyikan ke sini agar hanya dapat diakses di branch terpilih`,
  _ = `Seret ikon ke sini untuk membuatnya terlihat secara publik untuk semua pelanggan`,
  _ = `Seret ikon-ikon ini ke set branch di bawah ini untuk mengatur visibilitas berdasarkan branch`,
  _ = `Seret ikon-ikon ini ke kotak di atas untuk mengatur visibilitas ke publik`,
  _ = `menunggu publikasi`,
  _ = `File Penanda yang Dipublikasikan`,
  _ = `Semua set branch dan ikon publik di atas dapat memberikan penanda khusus di garis waktu pada branch-branch berikutnya. Jika terdapat set branch yang tidak memiliki ikon yang dipublikasikan, maka semua branch di dalamnya tidak akan berkontribusi:`,
  _ = `Set branch ini tidak memiliki set file sendiri yang dipublikasikan. Pelanggan dalam branch-branch di dalamnya akan kembali menggunakan penanda garis waktu yang ada di branch default.`,
  _ = `dummy`,
  _ = `Pencapaian`,
  _ = `%1$s%`,
  _ = `Set Pencapaian`,
  _ = `Gunakan set untuk mengelola pembatasan akses dan visibilitas untuk kumpulan pencapaian. Sebagai contoh, kamu mungkin menginginkan set pencapaian yang hanya tersedia untuk pemilik DLC tertentu.`,
  _ = `Ringkasan`,
  _ = `Desain`,
  _ = `Persyaratan`,
  _ = `Merilis`,
  _ = `Menguji`,
  _ = `Definisikan dan perbarui pencapaian game-mu.`,
  _ = `Untuk hasil terbaik, ikon pencapaian harus merupakan gambar PNG berukuran 256 x 256 px atau paling kecil berukuran 64 x 64 px. Namun, disarankan untuk menggunakan ukuran yang lebih besar. Sebaiknya, ikon pencapaian yang sudah didapatkan dibuat penuh warna dan ikon pencapaian yang belum didapatkan dibuat berwarna abu-abu.`,
  _ = `Karena pencapaian dapat muncul di berbagai tempat di Komunitas Steam, nama dan ikon yang dimasukkan harus pantas untuk dilihat oleh semua usia dan pengguna. Valve dapat menghapus game sepenuhnya dari toko jika pencapaiannya melanggar <1>Pedoman konten komunitas</1> atau menyinggung.`,
  _ = `Untuk sepenuhnya mengaktifkan Pencapaian, dan untuk melengkapi daftar periksa perilisan, kamu juga harus mencentang kotak yang sesuai pada informasi halaman tokomu, di bagian <1>"Fitur yang Didukung"</1>.`,
  _ = `Sebelum dirilis, <1>kamu dapat melihat pratinjau pencapaianmu di sini</1>. Status rilis pencapaian akan ditampilkan di halaman ini.`,
  _ = `Buat Set Baru`,
  _ = `Buat set baru atau set DLC untuk pencapaian`,
  _ = `Base game`,
  _ = `Gunakan set ini untuk menentukan pencapaian yang berlaku untuk base game. Grup ini biasanya mencakup sebagian besar pencapaian.`,
